/**
 * Jinx Lil' Monsta + Psychopath: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Lil%27_Monsta
 * Wiki: https://wiki.bloodontheclocktower.com/Psychopath
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L116). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData, committedCharacters } from '#lib/core/testing/committed-data.ts';
import { warned } from '#lib/core/model/fixtures.test-support.ts';
import { executionSavers } from '#lib/core/rules/ability.ts';
import { gameEnds } from '#lib/core/rules/game-end.ts';
import { jinxRulesBetween } from '#lib/core/rules/jinxes.ts';
import { scenario } from '#lib/core/testing/scenario.ts';
import { babysits, scriptOf, withLilMonsta } from './lilmonsta.test-support.ts';

describe("Lil' Monsta + Psychopath jinx", () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'lilmonsta', 'psychopath');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('lilmonsta')?.name).toBe("Lil' Monsta");
		expect(data.byId.get('psychopath')?.name).toBe('Psychopath');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['lilmonsta', 'psychopath'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['lilmonsta'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['psychopath'])).not.toContain(jinx);
	});

	// Both pages' Related Jinxes: the Psychopath's roshambo doesn't save them from execution
	// while they babysit Lil' Monsta.
	describe('a Psychopath babysitting Lil’ Monsta dies when executed', () => {
		const cast = ['psychopath', 'poisoner', 'chef', 'empath', 'monk', 'mayor'];
		const base = withLilMonsta(cast);
		const saver = (s: typeof base) =>
			executionSavers(s.game, s.seat('psychopath'), s.characters).find(
				(x) => x.source.characterId === 'psychopath'
			);

		it("is data in the Psychopath's rules", () => {
			expect(jinxRulesBetween('psychopath', 'lilmonsta', committedCharacters())).toEqual({
				diesWhenExecuted: { when: [{ marked: 'Is The Demon' }] }
			});
		});

		it('offers the roshambo as a saver only while they do not babysit', () => {
			// Wiki: "If the Psychopath is babysitting Lil' Monsta, they die when executed."
			expect(saver(base)?.problem).toBeUndefined();
			expect(saver(babysits(base, 'psychopath'))?.problem).toBe('jinxed');
		});

		it('warns on saving them anyway, records it, and dies otherwise so good wins', () => {
			// Wiki: "If the Psychopath is babysitting Lil' Monsta, they die when executed."
			const s = babysits(base, 'psychopath').nominate('chef', 'psychopath');
			const command = {
				type: 'Execute' as const,
				seatId: s.seat('psychopath'),
				savedBy: 'psychopath'
			};
			expect(warned(s.session, s.ctx, command)).toContain('save-may-not-apply');
			// Warn, never lock: the Storyteller may still say the roshambo saved them.
			expect(s.do(command).game.seats[s.seat('psychopath')].dead).toBe(false);
			const executed = s.execute('psychopath');
			expect(executed.game.seats[s.seat('psychopath')].dead).toBe(true);
			expect(gameEnds(executed.game, executed.characters)).toMatchObject([
				{ rule: 'demon-dead', winner: 'good' }
			]);
		});

		it('does not apply with no Lil’ Monsta on the script', () => {
			const plain = scenario(cast, { script: scriptOf(cast) }).reminder(
				'psychopath',
				'lilmonsta',
				'Is The Demon'
			);
			expect(saver(plain)?.problem).toBeUndefined();
		});
	});
});
